{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is neutral or negative (sentiment ≤ 0.33) and historical prices show downward momentum.",
    "Increase forecast sensitivity to recent price spikes (last 5-7 days) when sentiment is positive (sentiment ≥ 0.50) to avoid underestimating upward momentum.",
    "Apply mean reversion correction: if forecast is > 10% above recent 30-day average, reduce by 5-10% unless sentiment strongly bullish.",
    "Reduce forecast overshoot after sharp spikes (≥ 15% above prior peak) by 10-20% to prevent overcorrection.",
    "When sentiment is consistently low (≤ 0.00) and prices are trending down, apply a lagged correction: forecast = prior 30-day true value - 0.5x recent decline rate.",
    "For long-term horizons (>14 days), reduce forecast volatility by 15-20% to account for diminishing momentum and increased noise."
  ]
}
